description:
Implement a `useIsMounted` hook that returns a stable getter function. Calling the getter returns `true` while the component is mounted and `false` after it unmounts. Use a ref — do NOT use state.

**Example:**
```tsx
const isMounted = useIsMounted();
fetch('/api/data').then(res => {
  if (isMounted()) setState(res);
});
```

starter_code:
import { useEffect, useRef, useCallback } from 'react';

export function useIsMounted(): () => boolean {
  // your code here
}

test_suite:
test('returns a function', () => {
  const { result } = renderHook(() => useIsMounted());
  expect(typeof result.current).toBe('function');
});

test('getter returns true while mounted', () => {
  const { result } = renderHook(() => useIsMounted());
  expect(result.current()).toBe(true);
});

test('getter returns false after unmount', () => {
  const { result, unmount } = renderHook(() => useIsMounted());
  unmount();
  expect(result.current()).toBe(false);
});

// __hidden__
test('getter stays stable across rerenders', () => {
  const { result, rerender } = renderHook(() => useIsMounted());
  const first = result.current;
  rerender();
  expect(result.current).toBe(first);
});

solution:
import { useEffect, useRef, useCallback } from 'react';

export function useIsMounted(): () => boolean {
  const mountedRef = useRef(false);

  useEffect(() => {
    mountedRef.current = true;
    return () => { mountedRef.current = false; };
  }, []);

  return useCallback(() => mountedRef.current, []);
}
